<main class="container py-5"><div class="dashboard-head"><div><span class="eyebrow">ESPACE MEMBRE</span><h1 class="fw-bold">Mes réservations</h1></div><a href="/activites" class="btn btn-accent">Trouver une séance</a></div><?php if(!$items): ?><div class="empty-state"><i class="bi bi-calendar2-x"></i><h3>Aucune réservation</h3><p>Votre prochaine séance vous attend.</p></div><?php endif; ?><div class="row g-4"><?php foreach($items as $x): ?><div class="col-lg-6"><div class="reservation-card"><img src="<?=e($x['image_url'])?>" alt=""><div class="p-3 flex-grow-1"><div class="d-flex justify-content-between"><h3 class="h5 fw-bold"><?=e($x['title'])?></h3><span class="badge text-bg-<?=$x['status']==='confirmed'?'success':($x['status']==='completed'?'primary':'secondary')?>"><?=e($x['status'])?></span></div><p class="mb-2"><i class="bi bi-calendar-event"></i> <?=date('d/m/Y H:i',strtotime($x['starts_at']))?> · <?=e($x['coach_name'])?></p><?php if($x['status']==='confirmed' && strtotime($x['starts_at'])>time()): ?><form method="post" action="/annuler" onsubmit="return confirm('Annuler cette réservation ?')"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="id" value="<?=$x['id']?>"><button class="btn btn-sm btn-outline-danger">Annuler</button></form><?php endif; ?><?php if(strtotime($x['starts_at'])<time() || $x['status']==='completed'): ?><button class="btn btn-sm btn-outline-dark mt-2" data-bs-toggle="collapse" data-bs-target="#review<?=$x['id']?>">Donner un avis</button><form id="review<?=$x['id']?>" class="collapse mt-3" method="post" action="/avis"><input type="hidden" name="csrf" value="<?=csrf()?>"><input type="hidden" name="activity_id" value="<?=$x['activity_id']?>"><select name="rating" class="form-select form-select-sm mb-2"><option value="5">5 - Excellent</option><option value="4">4 - Très bien</option><option value="3">3 - Bien</option><option value="2">2 - Moyen</option><option value="1">1 - Décevant</option></select><textarea name="comment" class="form-control form-control-sm mb-2" required placeholder="Votre expérience"></textarea><button class="btn btn-accent btn-sm">Envoyer</button></form><?php endif; ?></div></div></div><?php endforeach; ?></div></main>